void testSystemCredentialsProviderCredentials() throws Exception {
    final AuthenticatorDelegate authenticatorDelegate = installAuthenticator(AUTH1);
    final URL httpRequestUrl = new URL(TARGET_SCHEME1, TARGET_HOST1, TARGET_PORT1, "/");
    final AuthScope authScope = new AuthScope(PROXY_PROTOCOL1, PROXY_HOST1, PROXY_PORT1, PROMPT1, StandardAuthScheme.BASIC);
    final HttpClientContext context = HttpClientContext.create();
    context.setRequest(new HttpGet(httpRequestUrl.toURI()));
    final Credentials receivedCredentials = new SystemDefaultCredentialsProvider().getCredentials(authScope, context);
    Mockito.verify(authenticatorDelegate).getPasswordAuthentication(PROXY_HOST1, null, PROXY_PORT1, PROXY_PROTOCOL1, PROMPT1, StandardAuthScheme.BASIC.toUpperCase(Locale.ROOT), httpRequestUrl, RequestorType.SERVER);
    Assertions.assertNotNull(receivedCredentials);
    Assertions.assertEquals(AUTH1.getUserName(), receivedCredentials.getUserPrincipal().getName());
}

