void testLeaseExistingConnectionReturned() throws Exception {
    final PoolEntry<String, HttpConnection> poolEntry = new PoolEntry<>(DEFAULT_ROUTE);
    final HttpConnection conn = Mockito.mock(HttpConnection.class);
