    }
    final String token = buf.toString();
    configureServerWithBasicAuth(bootstrap -> bootstrap.register("*", AsyncEchoHandler::new).setExchangeHandlerDecorator(requestHandler -> new AuthenticatingAsyncDecorator(requestHandler, new BearerAuthenticationHandler(), new BasicTestAuthenticator(token, "test realm"))));
