void testBasicAuthenticationCredentialsCachingByPathPrefix() throws Exception {
    configureServerWithBasicAuth(bootstrap -> bootstrap.register("*", AsyncEchoHandler::new));
    final HttpHost target = startServer();
    final DefaultAuthenticationStrategy authStrategy = Mockito.spy(new DefaultAuthenticationStrategy());
    final Queue<HttpResponse> responseQueue = new ConcurrentLinkedQueue<>();
    configureClient(builder -> builder.setTargetAuthenticationStrategy(authStrategy).addResponseInterceptorFirst((response, entity, context) -> responseQueue.add(BasicResponseBuilder.copy(response).build())));
    final TestAsyncClient client = startClient();
    final CredentialsProvider credentialsProvider = CredentialsProviderBuilder.create().add(target, "test", "test".toCharArray()).build();
    final AuthCache authCache = new BasicAuthCache();
    for (final String requestPath : new String[] { "/blah/a", "/blah/b?huh", "/blah/c", "/bl%61h/%61" }) {
        final HttpClientContext context = HttpClientContext.create();
        context.setAuthCache(authCache);
        context.setCredentialsProvider(credentialsProvider);
        final Future<SimpleHttpResponse> future = client.execute(SimpleRequestBuilder.get().setHttpHost(target).setPath(requestPath).build(), context, null);
        final HttpResponse response = future.get();
        Assertions.assertNotNull(response);
        Assertions.assertEquals(HttpStatus.SC_OK, response.getCode());
    }
    // There should be only single auth strategy call for all successful message exchanges
    Mockito.verify(authStrategy).select(Mockito.any(), Mockito.any(), Mockito.any());
    assertThat(responseQueue.stream().map(HttpResponse::getCode).collect(Collectors.toList()), CoreMatchers.equalTo(Arrays.asList(401, 200, 200, 200, 200)));
    responseQueue.clear();
    authCache.clear();
